function [y] = kp_ap_nearest(to_ap, xi)
%KP_AP_NEAREST  Octave's interp1(x, y, xi, 'nearest') over a table of nodes (no extrapolation: nan outside [x(1), x(n)]); the breaks
%   are the midpoints, a tie going to the upper node.
%   to_ap: bool (passed true or false)
%   xi: real[1] (passed a plain number)
%   returns y: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    y = 0;
    n = 28;
    x0 = asils.pc.choose_lazy(to_ap, @() asils.models.kpap.KP_AP_KP(1), @() asils.models.kpap.KP_AP_AP(1));
    xn = asils.pc.choose_lazy(to_ap, @() asils.models.kpap.KP_AP_KP(((n - 1)) + 1), @() asils.models.kpap.KP_AP_AP(((n - 1)) + 1));
    if (~((xi >= x0) && (xi <= xn)))
        y = NaN;
    else
        k = 0;
        stop = false;
        for i = (0):(((n - 1)) - 1)
            a = asils.pc.choose_lazy(to_ap, @() asils.models.kpap.KP_AP_KP((i) + 1), @() asils.models.kpap.KP_AP_AP((i) + 1));
            b = asils.pc.choose_lazy(to_ap, @() asils.models.kpap.KP_AP_KP(((i + 1)) + 1), @() asils.models.kpap.KP_AP_AP(((i + 1)) + 1));
            if (~stop)
                if (((a + b) / 2) <= xi)
                    k = (i + 1);
                else
                    stop = true;
                end
            end
        end
        k = asils.pc.fmin(k, (n - 1));
        y = asils.pc.choose_lazy(to_ap, @() asils.models.kpap.KP_AP_AP((k) + 1), @() asils.models.kpap.KP_AP_KP((k) + 1));
    end
end
